pln.z=dot(surfp,vec3( 0.0 , 0.0 , 1.0 )); //cosine to plane
tuv.xyz=pln.y>0?( (abs(pln.x)<0.5)&&(abs(pln.z)<0.5)?pln.xzy:tuv):tuv;
pln.x=dot(prjN,vec3( 1.0 , 0.0 , 0.0 )); //cosine to plane
sp=dot(op,vec3( 1.0 , 0.0 , 0.0 ));
surfp=op-prjN*(1.0 / pln.xxx)*(sp+0.5);
pln.y=dot(surfp,vec3( 0.0 , 1.0 , 0.0 )); //cosine to plane
pln.z=dot(surfp,vec3( 0.0 , 0.0 , 1.0 )); //cosine to plane
