pln.x=-pln.x;
sp=-sp;
surfp=op-prjN*(1.0 / pln.xxx)*(sp+0.5);
pln.y=dot(surfp,vec3( 0.0 , 1.0 , 0.0 )); //cosine to plane
pln.z=dot(surfp,vec3( 0.0 , 0.0 , 1.0 )); //cosine to plane
tuv.xyz=pln.x>0?( (abs(pln.y)<0.5)&&(abs(pln.z)<0.5)?pln.yzx:tuv):tuv;
sp=tuv.x;
//b2=texture(base02,sqrt(1.0 - prjN.yz*prjN.yz)/prjN.xx * 20.0);//abs(prjN.z + 2.0))*0.7;
vec3 t1,t2,a1,a2;
/*
