b2=max(b2,texture(base02,-3*prjN.xy/(prjN.zz*prjN.zz * 2.0-3)));//abs(prjN.z + 2.0))*0.7;
b2=max(b2,texture(base02,-3*prjN.xz/(prjN.yy*prjN.yy * 2.0-3)));//abs(prjN.z + 2.0))*0.7;
b3=texture(base0,3.0 * prjN.yz/(prjN.xx*prjN.xx * 2.0-3));//abs(prjN.z + 2.0))*0.7;
b3=max(b3,texture(base01,3.0 * prjN.xy/(prjN.zz*prjN.zz * 2.0-3)));//abs(prjN.z + 2.0))*0.7;
b3=max(b3,texture(base01,3.0 * prjN.xz/(prjN.yy*prjN.yy * 2.0-3)));//abs(prjN.z + 2.0))*0.7;
*/
//a1=flaot3(prjN.x,prjN.y, 0.0 );
//a2=flaot3(prjN.x,prjN.y, 0.0 );
b2=texture(base01,sin(prjN.xy*M_PI))*abs(prjN.zzz);
b2=max(b2,texture(base01,sin(prjN.xz*M_PI))*abs(prjN.yyy));
b2=max(b2,texture(base01,sin(prjN.yz*M_PI))*abs(prjN.xxx));
