//ret=tex2d(base01,(uv-0.5)*(1.01-cp*0.02)+0.5+/*prjN.yz*/(op.xz/abs((op.yy * 2.0) + 30.0))*0.03);
//ret=ret*(0.6*(cp)+0.4)+b2*0.4*cp;
