(prjN.xy/abs(prjN.zz + 2.0))*0.016+(uv-0.5-0.016*(prjN.xy/abs(prjN.zz + 2.0)))*(1.0 - i*0.04)+0.5),
0.99-(0.85*(1.0 - i)));
